INSERT INTO "documents" VALUES('source_revisions','src-346f29b1daedff63a34f40bb:363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645','{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "path": "@COURSE@/inputs/notes.md", "status": "read", "verification": "pending", "units": [{"id": "line-1", "locator": {"line": 1}, "text": "# Superposition"}, {"id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude."}, {"id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes."}, {"id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude."}, {"id": "line-5", "locator": {"line": 5}, "text": "# States"}, {"id": "line-6", "locator": {"line": 6}, "text": "A state is a normalized vector; a global phase changes no probability."}, {"id": "line-7", "locator": {"line": 7}, "text": "# Measurement"}, {"id": "line-8", "locator": {"line": 8}, "text": "A measurement in a basis gives each outcome with the squared magnitude of its component."}], "errors": []}');
