INSERT INTO "documents" VALUES('practice_tasks','practice-d601cd6f-4d18-41a9-9681-b8bc8014f1dd:0','{"id": "practice-d601cd6f-4d18-41a9-9681-b8bc8014f1dd:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "Part (a) is right; check the sign in (b).", "outcome": "needs_work", "parts": ["correct", "not_yet"], "evidence_id": "practice-evidence:practice-e82fe9c7-8bd0-480f-9cee-89a9f66554b2", "kind": "needs_work", "answer": "(a) P = (1 + cos phi)/2. (b) phi = 0."}], "created_at": 1794558286.5986683, "parts": [{"label": "(a)", "text": "Find $P(\\phi)$."}, {"label": "(b)", "text": "When is it zero?"}]}');
