cbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream:181ec7be-3c08-4746-92bf-472faf86aadc", "role": "assistant", "text": "## Path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"amplitude\"}, {\"kind\": \"preference\", \"text\": \"Short steps with one formula each\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"title\": \"Path amplitudes\", \"remaining\": [{\"title\": \"Adding amplitudes\"}], \"check\": {\"idea\": \"What does a path carry?\", \"question\": \"What does a path carry?\", \"correct\": 0, \"options\": [{\"text\": \"A complex amplitude\", \"explanation\": \"Each path contributes an amplitude.\"}, {\"text\": \"A probability\", \"explanation\": \"Probabilities come only after adding.\"}]}}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 2}, {"id": "check-answer:181ec7be-3c08-4746-92bf-472faf86aadc", "role": "user", "text": "Check question: What does a path carry?\nAnswer: A probability", "concept_id": "paths", "kind": "check_answer", "supplied_source_refs": [], "source_refs": [], "source_context_concept_id": "paths", "sequence": 3}, {"id": "stream-user:step:694f8cfb-46dc-4618-9025-7650c4112a3e", "role": "user", "text": "Continue with the next step.", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 4}, {"id": "stream:step:694f8cfb-46dc-4618-9025-7650c4112a3e", "role": "assistant", "text": "## Adding amplitudes\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"interference term\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 5}, {"id": "stream:practice-d601cd6f-4d18-41a9-9681-b8bc8014f1dd", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$.\", \"parts\": [{\"label\": \"(a)\", \"text\": \"Find $P(\\\\phi)$.\"}, {\"label\": \"(b)\", \"text\": \"When is it zero?\"}], \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 6}, {"id": "stream-user:branch:cross-term", "role": "user", "text": "Why is the cross term 2 Re(a* b)?", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 7}, {"id": "stream:branch:cross-term", "role": "assistant", "text": "Because $|z|^2 = z^* z$, the cross terms give $2\\,\\mathrm{Re}(a^* b)$.\n<teaching-decision>{\"depth\": \"short\", \"category\": \"local\", \"rationale\": \"Local algebra\", \"suggest_supplement\": false, \"supplement_goal\": \"\"}</teaching-decision>\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"complex conjugate\"}], \"cleared\": []}</course-memory>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"},