INSERT INTO "documents" VALUES('stream_snapshots','practice-2c20dc82-03d1-4a28-bec9-a3420412e232','{"id": "practice-2c20dc82-03d1-4a28-bec9-a3420412e232", "attempts": [], "prompt_snapshot": {"context": {"concept": {"id": "paths", "title": "Adding path amplitudes", "objective": "Predict interference from two amplitudes", "links": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "exercises": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "question": "Find the probability for equal amplitudes.", "required_concepts": ["paths"]}]}, "chapter": {"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "prerequisites": [], "next_concept_id": "states", "sources": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "check-answer:181ec7be-3c08-4746-92bf-472faf86aadc", "role": "user", "text": "Check question: What does a path carry?\nAnswer: A probability", "concept_id": "paths", "kind": "check_answer", "supplied_source_refs": [], "source_refs": [], "source_context_concept_id": "paths", "sequence": 3}, {"id": "stream-user:step:694f8cfb-46dc-4618-9025-7650c4112a3e", "role": "user", "text": "Continue with the next step.", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 4}, {"id": "stream:step:694f8cfb-46dc-4618-9025-7650c4112a3e", "role": "assistant", "text": "## Adding amplitudes\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"interference term\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 5}, {"id": "stream:practice-d601cd6f-4d18-41a9-9681-b8bc8014f1dd", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$.\", \"parts\": [{\"label\": \"(a)\", \"text\": \"Find $P(\\\\phi)$.\"}, {\"label\": \"(b)\", \"text\": \"When is it zero?\"}], \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 6}, {"id": "stream-user:branch:cross-term", "role": "user", "text": "Why is the cross term 2 Re(a* b)?", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 7}, {"id": "stream:branch:cross-term", "role": "assistant", "text": "Because $|z|^2 = z^* z$, the cross terms give $2\\,\\mathrm{Re}(a^* b)$.\n<teaching-decision>{\"depth\": \"short\", \"category\": \"local\", \"rationale\": \"Local algebra\", \"suggest_supplement\": false, \"supplement_goal\": \"\"}</teaching-decision>\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"complex conjugate\"}], \"cleared\": []}</course-memory>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 8}, {"id": "stream-user:reply:cross-term:a658d8ba-d5ba-404f-9534-d202459e3a00", "role": "user", "text": "And when both amplitudes are real?", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 9}, {"id": "stream:reply:cross-term:a658d8ba-d5ba-404f-9534-d202459e3a00", "role": "assistant", "text": "## Lesson\n\nA state is a normalized vector.\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 10}]}, "language": "en", "chapters": [{"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"]}, {"id": "measurement", "title": "Measurement", "concept_ids": ["outcomes"]}], "learner_profile": {"goal": "Understand interference and measurement", "depth": "standard", "prerequisites": [{"topic": "Complex numbers", "level": "some", "check": "Multiplied two complex numbers"}], "focus": "Problem solving"}, "course_memory": {"preferences": ["Worked example before each new idea"], "taught_terms": [{"term": "amplitude", "concept_id": "paths"}, {"term": "interference term", "concept_id": "paths"}, {"term": "complex conjugate", "concept_id": "paths"}]}, "widgets": ["plot"]}}');
