INSERT INTO "documents" VALUES('interactions','practice-answer:practice-e82fe9c7-8bd0-480f-9cee-89a9f66554b2','{"id": "practice-answer:practice-e82fe9c7-8bd0-480f-9cee-89a9f66554b2", "role": "user", "text": "(a) P = (1 + cos phi)/2. (b) phi = 0.", "concept_id": "paths", "source_refs": [{"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-346f29b1daedff63a34f40bb", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 13}');
